        public const string YouTubeTranscript = "(async function () {\n  var sleep = function (ms) { return new Promise(function (r) { setTimeout(r, ms); }); };\n  var out = { segments: [], via: '', note: '', title: document.title };\n  if (/(^|\\.)consent\\.youtube\\.com$/.test(location.hostname) || document.querySelector('form[action*=\"consent.youtube.com\"]')) { out.note = 'consent'; return JSON.stringify(out); }\n  function scriptWith(re) {\n    var list = document.querySelectorAll('script');\n    for (var i = 0; i < list.length; i++) { var t = list[i].textContent || ''; if (re.test(t)) return t; }\n    return '';\n  }\n  function objAfter(text, marker) {\n    var at = text.indexOf(marker);\n    if (at < 0) return null;\n    var start = text.indexOf('{', at + marker.length);\n    if (start < 0) return null;\n    var depth = 0, inStr = false, esc = false;\n    for (var k = start; k < text.length; k++) {\n      var c = text[k];\n      if (inStr) { if (esc) esc = false; else if (c === '\\\\') esc = true; else if (c === '\"') inStr = false; continue; }\n      if (c === '\"') inStr = true;\n      else if (c === '{') depth++;\n      else if (c === '}' && --depth === 0) { try { return JSON.parse(text.slice(start, k + 1)); } catch (e) { return null; } }\n    }\n    return null;\n  }\n  function find(o, key, depth) {\n    if (!o || typeof o !== 'object' || depth > 60) return null;\n    if (Object.prototype.hasOwnProperty.call(o, key)) return o[key];\n    var vals = Array.isArray(o) ? o : Object.keys(o).map(function (k) { return o[k]; });\n    for (var i = 0; i < vals.length; i++) { var r = find(vals[i], key, depth + 1); if (r) return r; }\n    return null;\n  }\n  function fromRenderers(list) {\n    var segs = [];\n    (list || []).forEach(function (it) {\n      var r = it && it.transcriptSegmentRenderer;\n      if (!r) return;\n      var sn = r.snippet || {};\n      var text = (sn.runs || []).map(function (x) { return x.text || ''; }).join('') || sn.simpleText || '';\n